export const halfPlane = ([ox, oy]: Pt, [nx, ny]: Pt, L = 5000): Poly => {
  const [tx, ty] = [-ny, nx]
  return [[ox + tx * L, oy + ty * L], [ox - tx * L, oy - ty * L], [ox - tx * L + nx * L, oy - ty * L + ny * L], [ox + tx * L + nx * L, oy + ty * L + ny * L]]
