    }
  } else {
    add({ id: 'use', name: `Use conditions in ${zone.code}`, value: 'not modelled', limit: '—', status: 'check', ref: zoneRef(zone, 'permitted uses'), note: `Only ${SCOPE_ZONE} use conditions are modelled.` })
  }

