/** GeoJSON of context buildings, dropping any that overlap the plot (assumed cleared). */
export const contextGeoJSON = (ctx: Context, plot: LL[]) => {
  const pr = projector(plot[0])
  const plotM = plot.map(pr.toM)
  const feats = []
  for (const b of ctx.buildings) {
    const ring = b.g.slice(0, -1)
    if (ring.length < 3) continue
    const m = ring.map(pr.toM)
    if (m.some(v => pointInPoly(v, plotM)) || plotM.some(v => pointInPoly(v, m))) continue
    const a = area(m)
    const [h, basis] = buildingHeight(b, a)
    feats.push({ type: 'Feature' as const, properties: { h, basis, n: b.n ?? '' }, geometry: { type: 'Polygon' as const, coordinates: [b.g] } })
  }
  return { type: 'FeatureCollection' as const, features: feats }
}

