import { useEffect, useRef, useState } from 'react'
import type { Ctx, Result } from './designs'
import type { Req, Res } from './analyse.worker'

/** Runs `analyse` off the main thread. Only the newest input is computed; stale ones are dropped. */
export const useAnalysis = <T>(input: { ctx: Ctx; tag: T } | null) => {
  const [out, setOut] = useState<{ r: Result; tag: T; ms: number; error?: undefined } | { error: string; tag: T } | null>(null)
  const w = useRef<Worker | null>(null)
  const st = useRef({ busy: false, next: null as { ctx: Ctx; tag: T } | null, id: 0, tags: new Map<number, T>() })

  useEffect(() => {
    const worker = new Worker(new URL('./analyse.worker.ts', import.meta.url), { type: 'module' })
    w.current = worker
    const s = st.current
    const pump = () => {
      if (s.busy || !s.next) return
      const { ctx, tag } = s.next
      s.next = null
      s.busy = true
      s.tags.set(++s.id, tag)
      worker.postMessage({ id: s.id, ctx } satisfies Req)
    }
    worker.onmessage = (e: MessageEvent<Res>) => {
      const tag = s.tags.get(e.data.id) as T
      s.tags.delete(e.data.id)
      s.busy = false
      setOut('error' in e.data ? { error: e.data.error, tag } : { r: e.data.r, tag, ms: e.data.ms })
      pump()
    }
    ;(st.current as unknown as { pump: () => void }).pump = pump
    pump()
    return () => worker.terminate()
  }, [])

  useEffect(() => {
    if (!input) return
    st.current.next = input
    ;(st.current as unknown as { pump?: () => void }).pump?.()
  }, [input])

  return out
}

