    expect(parseKml(ge)).toEqual(pts)
  })
  it('rejects a file with no polygon', () => {
    expect(() => parseKml('<kml><Placemark><Point><coordinates>100,13,0</coordinates></Point></Placemark></kml>')).toThrow()
  })
})
