}, [s])

const centre = useMemo(() => meanLL(s.pts), [s.pts])
const inSnap = covers(snapshot, centre)
const ctx = inSnap ? snapshot : live.ctx

useEffect(() => {
  if (!snapshot || inSnap) return
  if (live.ctx && covers(live.ctx, centre)) return
  setLive(l => ({ ...l, status: 'Loading surrounding buildings from OpenStreetMap (can take 20–40 s outside the bundled Sukhumvit area). Rules and designs are already up to date.' }))
  const t = setTimeout(() => {
